style.css:
@-moz-document domain("classroom.google.com") {
/* Core page elements */
  body, .RQOga, .Q1zXEd, .gLuVy, .Q2pOec, .J1Jwrf, .r6xJkc {
    background: url("https://www.nawpic.com/media/2020/aesthetic-desktop-nawpic-4-e1605819181323.png") #1C1C1C top fixed no-repeat !important;
  }

  /* Dark panels and cards */
  .QkHtAc, .BvShCb, .muOPrd, .H2wzZe, .QzFmtc, .TwyJsf, .oZOTib, .iDF5Ec {
    background-color: #1b2022 !important;
    opacity: 0.8;
    backdrop-filter: blur(5px);
  }

  /* Hover & focus states */
  .QkHtAc:hover, .BvShCb:focus, .muOPrd:hover, .H2wzZe:focus {
    background-color: #323639 !important;
  }

  /* Text colors */
  .LJMQVe, .zKb7Yc, .PPh1Ad, .lmGf3c, .nTB-Gf, .xXQG0c, a, .yjZwC, .zqVj0 {
    color: #eee !important;
  }
  a:visited {
    color: #ddd !important;
  }

  /* Borders */
  .QkHtAc, .BvShCb, .muOPrd, .H2wzZe, .QzFmtc {
    border: 1px solid rgba(255,255,255,0.8) !important;
  }

  /* Dialogs, menus, pickers (Docs/Drive integration) */
  .docs-hue-picker, .picker-dialog, .lhs-dialog, .kh-dialog, .m9v25 .uAlU6 {
    background-color: #131719 !important;
    color: #fff !important;
    border-color: #323639 !important;
  }

  /* Blur translucent overlays */
  .picker-dialog-backdrop, .F7l5Ob-lPRnje, .iph-dialog, .J1Jwrf, .gLuVy {
    backdrop-filter: blur(20px);
    background: rgba(0,0,0,0) !important;
  }

  /* Profile menu (top-right) */
  .gb_Ab, .gb_Eb, .gb_Mb, .gb_ja, .gb_zb, .gb_Db {
    background: #1b2022 !important;
    border-color: #fff !important;
    color: #fff !important;
  }
  .gb_Ab:hover, .gb_Mb:hover, .gb_ja:hover {
    background: #323639 !important;
    border-color: #323639 !important;
  }
}
